.ds-mobile-menu {display: block;}
.ds-mobile-menu > summary {display: flex; gap: 15px; align-items: center; justify-content: space-between; min-height: 48px; padding: 11px 14px; border: 1px solid var(--color-navy, #1c1c58); cursor: pointer; list-style: none; font-size: 15px;}
.ds-mobile-menu > summary::-webkit-details-marker {display: none;}
.ds-menu-symbol {width: 18px; height: 12px; position: relative;}
.ds-menu-symbol::before {content: ""; position: absolute; width: 18px; height: 1px; background: currentColor; top: 2px; transition: transform var(--transition, 220ms cubic-bezier(.22, 1, .36, 1));}
.ds-menu-symbol::after {content: ""; position: absolute; width: 18px; height: 1px; background: currentColor; top: 2px; transition: transform var(--transition, 220ms cubic-bezier(.22, 1, .36, 1));}
.ds-menu-symbol::after {top: 10px;}
.ds-mobile-menu[open] .ds-menu-symbol::before {transform: translateY(4px) rotate(45deg);}
.ds-mobile-menu[open] .ds-menu-symbol::after {transform: translateY(-4px) rotate(-45deg);}
.ds-mobile-menu nav {display: grid; padding: 16px 22px 24px; position: absolute; z-index: 20; left: calc(-1 * var(--space-page,clamp(20px, 5.2vw, 96px))); right: calc(-1 * var(--space-page,clamp(20px, 5.2vw, 96px))); top: 100%; max-height:75vh;max-height:75dvh;overflow-y:auto;color: var(--color-navy, #1c1c58); background: var(--color-white, #ffffff); border-bottom: 2px solid var(--color-green, #70c875); box-shadow: 0 15px 25px -20px #0009;}
.ds-mobile-menu nav a {display: flex; gap: 20px; align-items: center; justify-content: space-between; text-decoration: none; padding: 13px 4px; min-height: 48px; font-size: 17px;}
.ds-mobile-menu nav a:hover {color: var(--color-green-ink, #337f40);}
.ds-mobile-menu nav .ds-mobile-menu-contact {margin-top: 10px; color: var(--color-navy, #1c1c58); background: var(--color-green, #70c875); padding-inline: 15px; font-weight: 700;}
.ds-mobile-menu nav .ds-mobile-menu-contact:hover {color: var(--color-navy, #1c1c58); background: var(--color-green-hover, #8ad38e);}
.ds-stage {min-height:620px;max-width:440px;background:var(--color-white,#fff);} .ds-mobile-menu {position:relative;} .ds-mobile-menu nav {left:0;right:0;} .ds-icon {display:inline-block;width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;}
