.ds-stage {font-family:var(--font-body,"Instrument Sans",Arial,sans-serif);font-size:16px;line-height:1.55;color:var(--color-navy,#1c1c58);padding:24px;} .ds-stage :focus-visible {outline:3px solid currentColor;outline-offset:6px;}
.ds-process-steps { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 28px; counter-reset: process; list-style: none; padding: 0; margin: 0; }
.ds-process-steps li { counter-increment: process; position: relative; text-align: center; }
.ds-process-steps li::before { content: counter(process, decimal-leading-zero); position: relative; z-index: 1; display: grid; place-items: center; width: 64px; height: 64px; margin: 0 auto 26px; border-radius: 50%; color: var(--color-white,#ffffff); background: var(--color-navy,#1c1c58); font-size: 25px; font-weight: 700; line-height: 1; font-variant-numeric: tabular-nums; }
.ds-process-steps li:not(:last-child)::after { content: ""; position: absolute; left: calc(50% + 44px); right: calc(-50% + 16px); top: 32px; height: 1px; background: var(--color-green,#70c875); }
.ds-process-steps h3 { font-size: 20px; line-height: 1.25; letter-spacing: -.02em; }
.ds-process-steps p { margin-top: 14px; font-size: 15px; line-height: 1.65; color: var(--color-muted,#5c5d76); }
.ds-process-action { display: flex; width: fit-content; margin: 36px auto 0; }

 @media(max-width:900px) {.ds-process-steps {grid-template-columns:repeat(3,minmax(0,1fr));gap:32px;} .ds-process-steps li:not(:last-child)::after {display:none;}} @media(max-width:760px) {.ds-process-steps {grid-template-columns:1fr;gap:28px;} .ds-process-steps li {padding:0 0 0 70px;text-align:left;} .ds-process-steps li::before {position:absolute;left:0;top:0;width:48px;height:48px;margin:0;font-size:20px;} .ds-process-steps li:not(:last-child)::after {display:block;left:24px;top:58px;bottom:-18px;right:auto;width:1px;height:auto;} .ds-process-steps h3 {font-size:22px;} .ds-process-steps h3 br {display:none;}}

