.ds-trade { position: relative; display: flex; align-items: end; isolation: isolate; min-height: 360px; padding: 26px; border-radius: var(--radius-card,18px); overflow: hidden; color: var(--color-white,#ffffff); background: var(--color-navy,#1c1c58); text-decoration: none; box-shadow: var(--shadow-card,0 12px 30px -18px #1c1c5840); }
.ds-trade::before { content: ""; position: absolute; inset: 0; z-index: -1; background: linear-gradient(180deg, #1c1c5800 5%, #1c1c5844 24%, #1c1c58ed 55%, var(--color-navy,#1c1c58) 100%); }
.ds-trade > img { position: absolute; inset: 0; z-index: -2; width: 100%; height: 100%; object-fit: cover; transition: transform 600ms var(--ease,cubic-bezier(.22, 1, .36, 1)); }
.ds-trade:hover > img { transform: scale(1.035); }
.ds-trade-copy { width: 100%; }
.ds-trade h4 { max-width: 26ch; font-size: 24px; line-height: 1.2; font-weight: 700; letter-spacing: -.02em; text-wrap: balance; }
.ds-trade p { max-width: 40ch; margin-top: 13px; color: var(--color-on-dark-muted,#d2d5e7); font-size: 15px; line-height: 1.55; }
.ds-trade-link { display: inline-flex; align-items: center; justify-content: space-between; gap: 14px; min-height: 44px; margin-top: 22px; padding: 11px 17px; border-radius: var(--radius-button,999px); color: var(--color-navy,#1c1c58); background: var(--color-green,#70c875); font-size: 13px; line-height: 1.4; font-weight: 700; transition: background-color var(--transition,220ms cubic-bezier(.22,1,.36,1)); }
.ds-trade-link .ds-icon { width: 18px; height: 18px; flex-basis: 18px; }
.ds-trade:hover .ds-trade-link { background: var(--color-green-hover,#8ad38e); }
