.ds-trade-filters button[aria-pressed="true"] { color: var(--color-white,#ffffff); background: var(--color-navy,#1c1c58); border-color: var(--color-navy,#1c1c58); box-shadow: 0 8px 18px -12px #1c1c5880; }
